import{_ as t,a,c as i,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 84 On strike","description":"学习 将来进行时与过程，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 84 On strike","description":"学习 将来进行时与过程，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 将来进行时与过程，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 83 After the elections","link":"/life/english/new-concept/book-2/unit-04/lesson-083"},"next":{"text":"第二册：实践与进步 · Lesson 85 Never too old to learn","link":"/life/english/new-concept/book-2/unit-04/lesson-085"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 83 After the elections","link":"/life/english/new-concept/book-2/unit-04/lesson-083"},"next":{"text":"第二册：实践与进步 · Lesson 85 Never too old to learn","link":"/life/english/new-concept/book-2/unit-04/lesson-085"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-084.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-084.md"}'),o={name:"life/english/new-concept/book-2/unit-04/lesson-084.md"};function s(l,e,r,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-84-on-strike" tabindex="-1">第二册：实践与进步 · Lesson 84 On strike <a class="header-anchor" href="#第二册-实践与进步-·-lesson-84-on-strike" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 84 On strike&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>劳资谈判中预期和实际进展不总一致；练习持续行动与将来安排的区别。本课的语言观察是：will be meeting 表未来某时正常安排中的会议过程，不表示谈判一定有结果；will have agreed 则是对达成协议的完成预测。完成学习后，请写一段中立谈判进度说明，分清已完成的准备和仍未达成的结果。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>worker</td><td>/ˈwɜːkə/</td><td>n.</td><td>工人</td><td>a factory worker</td></tr><tr><td>agreement</td><td>/əˈɡriːmənt/</td><td>n.</td><td>协议</td><td>reach an agreement</td></tr><tr><td>demand</td><td>/dɪˈmɑːnd/</td><td>n.</td><td>要求</td><td>a pay demand</td></tr><tr><td>negotiate</td><td>/nɪˈɡəʊʃieɪt/</td><td>v.</td><td>谈判</td><td>negotiate a deal</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>reach an agreement — 达成协议</li><li>go on strike — 开始罢工，strike 在此不用 a</li></ul><h2 id="语法讲解-将来进行时与过程" tabindex="-1">语法讲解：将来进行时与过程 <a class="header-anchor" href="#语法讲解-将来进行时与过程" aria-label="Permalink to &quot;语法讲解：将来进行时与过程&quot;">​</a></h2><p>将来进行时使用 will be 加动词 -ing，突出未来某个时间正在发生的过程，常用于说明正常安排中的活动。它与 will do 的区别主要是观察角度：一个看过程，一个把动作看成整体。句中须有明确或可推知的未来参照时间。不要把 will be 后面接原形误当进行时，也不要用它保证某项活动一定完成；完成结果需要其他表达。本课应用：will be meeting 表未来某时正常安排中的会议过程，不表示谈判一定有结果；will have agreed 则是对达成协议的完成预测。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>At ten tomorrow, the two sides will be discussing the revised offer.</p></blockquote><p>明天十点，双方将正在讨论修订后的提议。</p><p>will be discussing 为将来进行时，the two sides 是复数主语，revised 为过去分词定语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>discuss about the offer 多余 about；discuss 直接接宾语。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>将 two sides 与 revised offer 重读；对照 discussing 与 agreement 的不同重音。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>At ten tomorrow, the two sides will be discussing the revised offer. No agreement has been signed yet. Both groups have selected representatives for the meeting.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一段中立谈判进度说明，分清已完成的准备和仍未达成的结果。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：will be discussing 为将来进行时，the two sides 是复数主语，revised 为过去分词定语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：discuss about the offer 多余 about；discuss 直接接宾语。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>改正：They will discuss about the offer。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> They will discuss the offer.</p><p><strong>解析：</strong> discuss 是及物动词，无需 about。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>协议是否已经签署？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> No.</p><p><strong>解析：</strong> yet 与否定完成时表截至现在未完成。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>补全将来进行时：They will be ___ the offer.（discuss）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> discussing</p><p><strong>解析：</strong> will be 后接 -ing 表过程。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：将来进行时与过程。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-083">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-085">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(o,[["render",s]]);export{p as __pageData,b as default};
